-- Categories were free text. Keep any that name one on the list, ignoring
-- case and spaces, and file the rest under other.
UPDATE "expense" SET "category" = CASE WHEN lower(trim("category")) IN ('housing', 'utilities', 'groceries', 'dining', 'transport', 'health', 'insurance', 'household', 'childcare', 'pets', 'travel', 'entertainment', 'subscriptions', 'gifts', 'other') THEN lower(trim("category")) ELSE 'other' END;--> statement-breakpoint
UPDATE "expense_template" SET "category" = CASE WHEN lower(trim("category")) IN ('housing', 'utilities', 'groceries', 'dining', 'transport', 'health', 'insurance', 'household', 'childcare', 'pets', 'travel', 'entertainment', 'subscriptions', 'gifts', 'other') THEN lower(trim("category")) ELSE 'other' END;--> statement-breakpoint
UPDATE "split_rule" SET "category" = CASE WHEN lower(trim("category")) IN ('housing', 'utilities', 'groceries', 'dining', 'transport', 'health', 'insurance', 'household', 'childcare', 'pets', 'travel', 'entertainment', 'subscriptions', 'gifts', 'other') THEN lower(trim("category")) ELSE 'other' END WHERE "category" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "expense" ALTER COLUMN "category" SET DEFAULT 'other';--> statement-breakpoint
ALTER TABLE "expense_template" ALTER COLUMN "category" SET DEFAULT 'other';--> statement-breakpoint
ALTER TABLE "expense" ADD CONSTRAINT "expense_category" CHECK ("expense"."category" in ('housing', 'utilities', 'groceries', 'dining', 'transport', 'health', 'insurance', 'household', 'childcare', 'pets', 'travel', 'entertainment', 'subscriptions', 'gifts', 'other'));--> statement-breakpoint
ALTER TABLE "expense_template" ADD CONSTRAINT "expense_template_category" CHECK ("expense_template"."category" in ('housing', 'utilities', 'groceries', 'dining', 'transport', 'health', 'insurance', 'household', 'childcare', 'pets', 'travel', 'entertainment', 'subscriptions', 'gifts', 'other'));--> statement-breakpoint
ALTER TABLE "split_rule" ADD CONSTRAINT "split_rule_category" CHECK ("split_rule"."category" is null or "split_rule"."category" in ('housing', 'utilities', 'groceries', 'dining', 'transport', 'health', 'insurance', 'household', 'childcare', 'pets', 'travel', 'entertainment', 'subscriptions', 'gifts', 'other'));
